WITH monthly_sales AS ( SELECT cp.cp_department, date_trunc('month', d.d_date) AS month, SUM(cs.cs_ext_sales_price) AS monthly_sales FROM catalog_sales cs INNER JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk INNER JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk WHERE d.d_year BETWEEN 2021 AND 2022 GROUP BY cp.cp_department, date_trunc('month', d.d_date) ), sales_lag AS ( SELECT cp_department, month, monthly_sales, LAG(monthly_sales) OVER (PARTITION BY cp_department ORDER BY month) AS prev_month_sales, CASE WHEN LAG(monthly_sales) OVER (PARTITION BY cp_department ORDER BY month) = 0 THEN NULL ELSE (monthly_sales - LAG(monthly_sales) OVER (PARTITION BY cp_department ORDER BY month)) / LAG(monthly_sales) OVER (PARTITION BY cp_department ORDER BY month) END AS pct_change FROM monthly_sales ), dept_avg AS ( SELECT cp_department, AVG(monthly_sales) AS avg_monthly_sales FROM monthly_sales GROUP BY cp_department ) SELECT s.cp_department, s.month, s.monthly_sales, s.prev_month_sales, s.pct_change, CASE WHEN s.pct_change IS NULL THEN 'No Prior Data' WHEN s.pct_change > 0.2 THEN 'Strong Growth' WHEN s.pct_change > 0 THEN 'Moderate Growth' ELSE 'Decline' END AS growth_category, DENSE_RANK() OVER (ORDER BY da.avg_monthly_sales DESC) AS dept_rank FROM sales_lag s JOIN dept_avg da ON s.cp_department = da.cp_department ORDER BY dept_rank, s.month
